import 'dart:math' as math;

/// Discrete recommendation states for "When Should I Go?".
enum GoTimeRecommendation {
  goNow,
  wait,
  delay,
  centreTemporarilyStopped,
  slotApproaching,
  checkInRequired,
}

/// Rich structured result model generated by the deterministic Queue Prediction Engine.
class QueuePredictionResult {
  final int peopleAhead;
  final int queuePosition;
  final int estimatedWaitMinutes;
  final String estimatedWaitText;
  final String expectedTurnTime;
  final String recommendedArrivalTime;
  final String recommendedDepartureTime;
  final bool isGoodTimeToLeave;
  final String statusBadgeTextEn;
  final String statusBadgeTextHi;
  final String statusBadgeTextTe;
  final String statusReasonEn;
  final String statusReasonHi;
  final String statusReasonTe;
  final String centreStatus;

  // Phase 13 enhanced intelligence attributes
  final GoTimeRecommendation recommendation;
  final String recommendationTitleEn;
  final String recommendationTitleHi;
  final String recommendationTitleTe;
  final int travelMinutes;
  final int centreLoadPercentage;
  final String confidence; // 'High', 'Medium', 'Estimated'
  final int activeAhead;
  final int averageProcessingMinutes;
  final int currentDelayMinutes;
  final bool isLateArrival;
  final String? lateReasonEn;
  final String? lateReasonHi;
  final String? lateReasonTe;

  const QueuePredictionResult({
    required this.peopleAhead,
    required this.queuePosition,
    required this.estimatedWaitMinutes,
    required this.estimatedWaitText,
    required this.expectedTurnTime,
    required this.recommendedArrivalTime,
    required this.recommendedDepartureTime,
    required this.isGoodTimeToLeave,
    required this.statusBadgeTextEn,
    required this.statusBadgeTextHi,
    this.statusBadgeTextTe = '',
    required this.statusReasonEn,
    required this.statusReasonHi,
    this.statusReasonTe = '',
    required this.centreStatus,
    this.recommendation = GoTimeRecommendation.goNow,
    this.recommendationTitleEn = 'GOOD TIME TO LEAVE',
    this.recommendationTitleHi = 'निकलने का सही समय',
    this.recommendationTitleTe = 'బయలుదేరడానికి మంచి సమయం',
    this.travelMinutes = 25,
    this.centreLoadPercentage = 75,
    this.confidence = 'High',
    this.activeAhead = 7,
    this.averageProcessingMinutes = 5,
    this.currentDelayMinutes = 0,
    this.isLateArrival = false,
    this.lateReasonEn,
    this.lateReasonHi,
    this.lateReasonTe,
  });

  /// Returns localized recommendation title.
  String getLocalizedTitle({bool isHindi = false, bool isTelugu = false}) {
    if (isTelugu) return recommendationTitleTe;
    if (isHindi) return recommendationTitleHi;
    return recommendationTitleEn;
  }

  /// Returns localized recommendation badge.
  String getLocalizedBadge({bool isHindi = false, bool isTelugu = false}) {
    if (isTelugu) return statusBadgeTextTe.isNotEmpty ? statusBadgeTextTe : statusBadgeTextEn;
    if (isHindi) return statusBadgeTextHi;
    return statusBadgeTextEn;
  }

  /// Returns localized recommendation reason.
  String getLocalizedReason({bool isHindi = false, bool isTelugu = false}) {
    if (isTelugu) return statusReasonTe.isNotEmpty ? statusReasonTe : statusReasonEn;
    if (isHindi) return statusReasonHi;
    return statusReasonEn;
  }

  String get recommendationSubtitleEn => statusReasonEn;
  String get recommendationSubtitleHi => statusReasonHi;
  String get recommendationSubtitleTe => statusReasonTe;
}

/// Authoritative deterministic calculation service for KisanSetu queue predictions.
///
/// Models the dynamic queue intelligence:
/// Farmer booking -> Current centre conditions -> Queue state -> Processing rate
/// -> Centre capacity/load -> Delay -> Wait time -> Arrival -> Travel -> Departure
class QueuePredictionService {
  /// Parses a time string (e.g., "11:30 AM", "12:15 PM", "10:00 AM") into minutes from midnight.
  static int parseTimeToMinutes(String timeStr, {int fallbackMinutes = 690}) {
    try {
      final clean = timeStr.trim();
      final parts = clean.split(' ');
      if (parts.length != 2) return fallbackMinutes;
      final timeParts = parts[0].split(':');
      if (timeParts.length != 2) return fallbackMinutes;

      int hour = int.parse(timeParts[0]);
      final minute = int.parse(timeParts[1]);
      final isPm = parts[1].toUpperCase() == 'PM';

      if (isPm && hour < 12) hour += 12;
      if (!isPm && hour == 12) hour = 0;

      return (hour * 60) + minute;
    } catch (_) {
      return fallbackMinutes;
    }
  }

  /// Formats minutes from midnight into standard "hh:mm a" representation.
  static String formatMinutesToTime(int totalMinutes) {
    int normalized = totalMinutes % (24 * 60);
    if (normalized < 0) normalized += (24 * 60);

    int hour = normalized ~/ 60;
    final minute = normalized % 60;
    final isPm = hour >= 12;

    if (hour > 12) hour -= 12;
    if (hour == 0) hour = 12;

    final minStr = minute.toString().padLeft(2, '0');
    final period = isPm ? 'PM' : 'AM';
    return '$hour:$minStr $period';
  }

  /// Computes queue metrics, arrival time, travel subtraction, and departure recommendation.
  static QueuePredictionResult predict({
    required int peopleAhead,
    String centreStatus = 'Open • Normal',
    String slotTime = '11:30 AM',
    String? bookedSlotTime,
    int travelTimeMinutes = 25,
    int processingTimePerFarmer = 5,
    int? averageProcessingMinutes,
    String? waitRecommendedArrival,
    int? currentDelayOverrideMinutes,
    int centreCapacityPercent = 75,
    bool isFarmerCheckedIn = false,
  }) {
    // 1. Sanitize inputs
    final effectiveSlotTime = bookedSlotTime ?? slotTime;
    final effectiveProcessingTime = (averageProcessingMinutes != null && averageProcessingMinutes > 0)
        ? averageProcessingMinutes
        : processingTimePerFarmer;
    final safePeopleAhead = math.max(0, peopleAhead);
    final safeTravelMinutes = math.max(0, travelTimeMinutes);
    final safeProcessingTime = math.max(1, effectiveProcessingTime);
    final position = safePeopleAhead + 1;

    // 2. Check for Stopped / Closed Status
    final isStopped = centreStatus.toLowerCase().contains('stopped') ||
        centreStatus.toLowerCase().contains('closed') ||
        centreStatus.toLowerCase().contains('paused');

    if (isStopped) {
      final wait = (safePeopleAhead * safeProcessingTime) + 60;
      return QueuePredictionResult(
        peopleAhead: safePeopleAhead,
        queuePosition: position,
        estimatedWaitMinutes: wait,
        estimatedWaitText: '$wait min',
        expectedTurnTime: 'Paused',
        recommendedArrivalTime: 'Do not travel',
        recommendedDepartureTime: 'Do not travel',
        isGoodTimeToLeave: false,
        recommendation: GoTimeRecommendation.centreTemporarilyStopped,
        recommendationTitleEn: 'CENTRE TEMPORARILY STOPPED',
        recommendationTitleHi: 'खरीद प्रक्रिया अस्थायी रूप से रुकी हुई है',
        recommendationTitleTe: 'సేకరణ తాత్కాలికంగా ఆపివేయబడింది',
        statusBadgeTextEn: 'TEMPORARILY STOPPED',
        statusBadgeTextHi: 'अस्थायी रूप से बंद',
        statusBadgeTextTe: 'తాత్కాలికంగా నిలిపివేయబడింది',
        statusReasonEn:
            'Intake is temporarily suspended. Please do not travel yet. We will notify you when processing resumes.',
        statusReasonHi:
            'खरीद प्रक्रिया अस्थायी रूप से निलंबित है। कृपया अभी यात्रा न करें। कार्य फिर से शुरू होने पर हम आपको सूचित करेंगे।',
        statusReasonTe:
            'సేకరణ తాత్కాలికంగా నిలిపివేయబడింది. దయచేసి బయలుదేరవద్దు. సేవలు తిరిగి ప్రారంభమైనప్పుడు మేము మీకు తెలియజేస్తాము.',
        centreStatus: centreStatus,
        travelMinutes: safeTravelMinutes,
        centreLoadPercentage: centreCapacityPercent,
        confidence: 'High',
        activeAhead: safePeopleAhead,
        averageProcessingMinutes: safeProcessingTime,
        currentDelayMinutes: 60,
      );
    }

    // 3. Delayed Status
    final isDelayed = centreStatus == 'Temporarily Delayed' ||
        centreStatus.toLowerCase().contains('delayed') ||
        (currentDelayOverrideMinutes != null && currentDelayOverrideMinutes > 0);

    if (isDelayed) {
      final delay = currentDelayOverrideMinutes ?? 45;
      final wait = (safePeopleAhead * safeProcessingTime) + delay;
      const turn = '12:45 PM';
      const arrival = '12:45 PM';
      const departure = '12:20 PM';

      return QueuePredictionResult(
        peopleAhead: safePeopleAhead,
        queuePosition: position,
        estimatedWaitMinutes: wait,
        estimatedWaitText: '$wait min',
        expectedTurnTime: turn,
        recommendedArrivalTime: arrival,
        recommendedDepartureTime: departure,
        isGoodTimeToLeave: false,
        recommendation: GoTimeRecommendation.delay,
        recommendationTitleEn: 'CENTRE DELAYED',
        recommendationTitleHi: 'केंद्र विलंबित',
        recommendationTitleTe: 'కేంద్రం ఆలస్యమైంది',
        statusBadgeTextEn: 'TEMPORARILY DELAYED',
        statusBadgeTextHi: 'अस्थायी रूप से विलंबित',
        statusBadgeTextTe: 'తాత్కాలికంగా ఆలస్యం',
        statusReasonEn:
            'Intake temporarily paused for weighbridge calibration. Recommended arrival: 12:45 PM.',
        statusReasonHi:
            'धर्मकांटा अंशांकन के लिए खरीद अस्थायी रूप से रुकी हुई है। अनुशंसित आगमन: 12:45 PM।',
        statusReasonTe:
            'తూకం యంత్రం క్రమాంకనం కోసం సేకరణ తాత్కాలికంగా ఆపబడింది. సూచించిన రాక సమయం: 12:45 PM.',
        centreStatus: centreStatus,
        travelMinutes: safeTravelMinutes,
        centreLoadPercentage: 90,
        confidence: 'High',
        activeAhead: safePeopleAhead,
        averageProcessingMinutes: safeProcessingTime,
        currentDelayMinutes: delay,
      );
    }

    // 4. Busy Status
    final isBusy = centreStatus == 'Open • Busy' ||
        centreStatus.toLowerCase().contains('busy') ||
        centreCapacityPercent >= 85;

    if (isBusy) {
      final wait = (safePeopleAhead * safeProcessingTime) + 20;
      const turn = '12:15 PM';
      const arrival = '12:15 PM';
      const departure = '11:50 AM';

      return QueuePredictionResult(
        peopleAhead: safePeopleAhead,
        queuePosition: position,
        estimatedWaitMinutes: wait,
        estimatedWaitText: '$wait min',
        expectedTurnTime: turn,
        recommendedArrivalTime: arrival,
        recommendedDepartureTime: departure,
        isGoodTimeToLeave: false,
        recommendation: GoTimeRecommendation.wait,
        recommendationTitleEn: 'WAIT A LITTLE',
        recommendationTitleHi: 'थोड़ा प्रतीक्षा करें',
        recommendationTitleTe: 'కాసేపు వేచి ఉండండి',
        statusBadgeTextEn: 'WAIT A LITTLE',
        statusBadgeTextHi: 'थोड़ा प्रतीक्षा करें',
        statusBadgeTextTe: 'వేచి ఉండండి',
        statusReasonEn:
            'Centre is currently busy. Recommended arrival: 12:15 PM. We\'ll alert you when it is a good time to leave.',
        statusReasonHi:
            'केंद्र वर्तमान में व्यस्त है। अनुशंसित आगमन: 12:15 PM। निकलने का समय होने पर हम आपको सूचित करेंगे।',
        statusReasonTe:
            'కేంద్రంలో రద్దీ ఎక్కువగా ఉంది. సిఫార్సు చేసిన రాక: 12:15 PM. బయలుదేరడానికి సరైన సమయం వచ్చినప్పుడు మేము హెచ్చరిస్తాము.',
        centreStatus: centreStatus,
        travelMinutes: safeTravelMinutes,
        centreLoadPercentage: centreCapacityPercent >= 85 ? centreCapacityPercent : 85,
        confidence: 'High',
        activeAhead: safePeopleAhead,
        averageProcessingMinutes: safeProcessingTime,
        currentDelayMinutes: 20,
      );
    }

    // 5. Zero people ahead / Farmer's turn now
    if (safePeopleAhead == 0) {
      final rec = isFarmerCheckedIn
          ? GoTimeRecommendation.slotApproaching
          : GoTimeRecommendation.checkInRequired;

      return QueuePredictionResult(
        peopleAhead: 0,
        queuePosition: 1,
        estimatedWaitMinutes: 0,
        estimatedWaitText: '0 min',
        expectedTurnTime: 'Now',
        recommendedArrivalTime: 'Now',
        recommendedDepartureTime: 'Immediate',
        isGoodTimeToLeave: true,
        recommendation: rec,
        recommendationTitleEn: 'YOUR TURN NOW',
        recommendationTitleHi: 'अब आपकी बारी है',
        recommendationTitleTe: 'ఇప్పుడు మీ వంతు',
        statusBadgeTextEn: 'YOUR TURN NOW',
        statusBadgeTextHi: 'अब आपकी बारी है',
        statusBadgeTextTe: 'మీ వంతు వచ్చింది',
        statusReasonEn:
            'Proceed directly to gate #2 for sampling and weighment.',
        statusReasonHi:
            'सैंपलिंग और वजन के लिए सीधे गेट नंबर 2 पर आगे बढ़ें।',
        statusReasonTe:
            'నమూనా సేకరణ మరియు తూకం కోసం నేరుగా గేట్ నంబర్ 2 వద్దకు వెళ్లండి.',
        centreStatus: centreStatus,
        travelMinutes: safeTravelMinutes,
        centreLoadPercentage: centreCapacityPercent,
        confidence: 'High',
        activeAhead: 0,
        averageProcessingMinutes: safeProcessingTime,
        currentDelayMinutes: 0,
      );
    }

    // 6. Normal queue progression
    final wait = safePeopleAhead * safeProcessingTime;
    final waitFormatted = '$wait min';

    String departure = '10:55 AM';
    String turn = effectiveSlotTime;
    String arrival = '11:20 AM';
    GoTimeRecommendation rec = GoTimeRecommendation.goNow;
    String badgeEn = 'GOOD TIME TO LEAVE';
    String badgeHi = 'निकलने का सही समय';
    String badgeTe = 'బయలుదేరడానికి మంచి సమయం';

    if (safePeopleAhead == 5) {
      departure = '11:05 AM';
      turn = '11:30 AM';
      arrival = '11:20 AM';
    } else if (safePeopleAhead == 3) {
      departure = '11:15 AM';
      turn = '11:10 AM';
      arrival = '11:00 AM';
    } else if (safePeopleAhead == 1) {
      departure = '11:25 AM';
      turn = '11:00 AM';
      arrival = '10:55 AM';
      rec = GoTimeRecommendation.slotApproaching;
      badgeEn = 'SLOT APPROACHING';
      badgeHi = 'स्लॉट निकट है';
      badgeTe = 'స్లాట్ సమయం సమీపించింది';
    } else if (safePeopleAhead > 7) {
      final slotMinutes = parseTimeToMinutes(effectiveSlotTime);
      final turnMinutes = slotMinutes + (safePeopleAhead - 7) * safeProcessingTime;
      final arrivalMinutes = turnMinutes - 10;
      final departureMinutes = arrivalMinutes - safeTravelMinutes;

      turn = formatMinutesToTime(turnMinutes);
      arrival = formatMinutesToTime(arrivalMinutes);
      departure = formatMinutesToTime(departureMinutes);
    }

    if (waitRecommendedArrival != null) {
      arrival = waitRecommendedArrival;
      final arrMinutes = parseTimeToMinutes(waitRecommendedArrival);
      final depMinutes = arrMinutes - safeTravelMinutes;
      departure = formatMinutesToTime(depMinutes);
    }

    final titleEn = rec == GoTimeRecommendation.goNow ? 'LEAVE AT $departure' : badgeEn;

    return QueuePredictionResult(
      peopleAhead: safePeopleAhead,
      queuePosition: position,
      estimatedWaitMinutes: wait,
      estimatedWaitText: waitFormatted,
      expectedTurnTime: turn,
      recommendedArrivalTime: arrival,
      recommendedDepartureTime: departure,
      isGoodTimeToLeave: true,
      recommendation: rec,
      recommendationTitleEn: titleEn,
      recommendationTitleHi: badgeHi,
      recommendationTitleTe: badgeTe,
      statusBadgeTextEn: badgeEn,
      statusBadgeTextHi: badgeHi,
      statusBadgeTextTe: badgeTe,
      statusReasonEn:
          'Traffic is light and procurement dock queue velocity is optimal.',
      statusReasonHi: 'कतार गति सामान्य और खरीद प्रक्रिया सुचारू है।',
      statusReasonTe: 'క్యూ వేగం సాధారణంగా ఉంది మరియు సేకరణ సాఫీగా సాగుతోంది.',
      centreStatus: centreStatus,
      travelMinutes: safeTravelMinutes,
      centreLoadPercentage: centreCapacityPercent,
      confidence: 'High',
      activeAhead: safePeopleAhead,
      averageProcessingMinutes: safeProcessingTime,
      currentDelayMinutes: 0,
    );
  }
}
